<?php
namespace App\Features\Profile\Livewire;
use Livewire\Component;use Livewire\WithFileUploads;use App\Features\Profile\Services\ProfileService;
class Profile extends Component {use WithFileUploads;public string $name='',$username='',$email='',$password='',$password_confirmation='';public $photo;public function mount(){$u=auth()->user();$this->name=$u->name;$this->username=$u->username;$this->email=$u->email??'';}public function save(ProfileService $service){$u=auth()->user();$data=$this->validate(['name'=>'required|string|max:120','username'=>'required|string|max:40|alpha_dash|unique:users,username,'.$u->id,'email'=>'nullable|email|max:150|unique:users,email,'.$u->id,'password'=>'nullable|string|min:8|confirmed','photo'=>'nullable|image|max:3072']);$service->update($u,$data,$this->photo);$this->reset(['password','password_confirmation','photo']);session()->flash('success','Profil berhasil diperbarui.');}public function render(){return view('livewire.profile.profile')->layout('components.layouts.app');}}
